#ifndef __MEM_CHAOSExMon_HH__
#define __MEM_CHAOSExMon_HH__

#include <random>
#include <string>
#include <cstdint>

#include "sim/sim_object.hh"
#include "mem/abstract_mem.hh"
#include "base/types.hh"
#include "params/CHAOSExMon.hh"
#include "base/output.hh"

namespace gem5
{

  // S3-7 (plan §5.4B): exclusive-monitor fault injector. The gem5 SE model
  // of ARM's local monitor is AbstractMemory::lockedAddrList
  // (trackLoadLocked on LDXR / checkLockedAddrList on stores). CHAOSExMon
  // self-attaches to the AbstractMemory (ctor sets memory->chaosExMon)
  // and corrupts the reservation lifecycle:
  //   clear_reservation  — drop a just-registered LDXR reservation
  //                       (chronic STXR failure)
  //   stale_reservation  — keep a reservation alive across a conflicting
  //                       write (STXR false-success, lost-update SDC)
  class CHAOSExMon : public SimObject
  {
    public:
      CHAOSExMon(const CHAOSExMonParams &p);
      ~CHAOSExMon();

      enum class Mode {
          ClearReservation,
          StaleReservation
      };

      // Hook 1 (called from AbstractMemory::trackLoadLocked AFTER the
      // reservation is registered): clear_reservation may drop it.
      void maybeDropReservation(memory::AbstractMemory *mem,
                                const RequestPtr &req, Addr paddr);

      // Hook 2 (called from AbstractMemory::checkLockedAddrList during the
      // erase loop, for a reservation owned by a DIFFERENT context than the
      // writer): stale_reservation may keep it alive. Returns true when the
      // reservation must NOT be erased (fault injected).
      bool maybeKeepReservation(memory::AbstractMemory *mem,
                                ContextID owner_cid, ContextID requestor_cid,
                                Addr paddr);

    private:
      Mode mode;
      float probability;
      uint64_t first_clock, last_clock;
      uint64_t max_faults;
      uint64_t faults_injected_count;
      bool in_window = false;      // first_clock reached
      bool write_log;
      std::mt19937 rng;
      OutputStream *log_stream = nullptr;

      bool shouldInject();
      void writeLog(const std::string &type, Addr paddr, ContextID cid);

      struct CHAOSExMonStats : public statistics::Group
      {
          statistics::Scalar numFaultsInjected;
          statistics::Scalar numClearReservations;   // LDXR reservations dropped
          statistics::Scalar numStaleReservations;   // erases suppressed
          statistics::Scalar numInWindowChecks;      // hook invocations in window
          statistics::Scalar numOutOfWindow;         // hook invocations pre-window

          CHAOSExMonStats(statistics::Group *parent);
      };

      std::unique_ptr<CHAOSExMonStats> stats;
  };

} // namespace gem5

#endif // __MEM_CHAOSExMon_HH__

#include "mem/CHAOSExMon/CHAOSExMon.hh"

#include "base/output.hh"
#include "base/types.hh"
#include "mem/abstract_mem.hh"
#include "mem/packet.hh"
#include "mem/request.hh"
#include "params/CHAOSExMon.hh"
#include "sim/sim_object.hh"

namespace gem5
{

  CHAOSExMon::CHAOSExMonStats::CHAOSExMonStats(statistics::Group *parent)
      : statistics::Group(parent, "CHAOSExMon"),
        ADD_STAT(numFaultsInjected, statistics::units::Count::get(),
                 "Total reservations corrupted (G5-capped)"),
        ADD_STAT(numClearReservations, statistics::units::Count::get(),
                 "LDXR reservations dropped (clear_reservation mode)"),
        ADD_STAT(numStaleReservations, statistics::units::Count::get(),
                 "reservation erases suppressed (stale_reservation mode)"),
        ADD_STAT(numInWindowChecks, statistics::units::Count::get(),
                 "hook invocations inside the injection window"),
        ADD_STAT(numOutOfWindow, statistics::units::Count::get(),
                 "hook invocations before first_clock (skipped)")
  {
  }

  CHAOSExMon::CHAOSExMon(const CHAOSExMonParams &p)
      : SimObject(p),
        probability(p.probability),
        first_clock(p.first_clock), last_clock(p.last_clock),
        max_faults(p.max_faults),
        faults_injected_count(0),
        write_log(p.write_log),
        rng(p.rng_seed),
        stats(std::make_unique<CHAOSExMonStats>(this))
  {
      const std::string &m = p.mode;
      if (m == "clear_reservation")      mode = Mode::ClearReservation;
      else if (m == "stale_reservation") mode = Mode::StaleReservation;
      else
          panic("CHAOSExMon: unknown mode '%s' "
                "(clear_reservation|stale_reservation)", m);

      // Self-attach to the host AbstractMemory (same pattern as
      // CHAOSArmTLB/CHAOSLSQFwd — no Python-side wiring beyond instantiating
      // the SimObject next to the memory).
      memory::AbstractMemory *mem = p.memory;
      if (!mem)
          warn("CHAOSExMon: no memory host — injector inert (no hook).");
      else
          mem->setChaosExMon(this);

      if (write_log) {
          std::string fname = "exmon_injections.log";
          log_stream = simout.findOrCreate(fname);
          *(log_stream->stream())
              << "CHAOSExMon attached, mode=" << m
              << " probability=" << probability
              << " first_clock=" << first_clock
              << " last_clock=" << last_clock
              << " max_faults=" << max_faults
              << " rng_seed=" << p.rng_seed << "\n";
      }
  }

  CHAOSExMon::~CHAOSExMon() = default;

  bool
  CHAOSExMon::shouldInject()
  {
      // Time window: curCycle of the HOST memory's system clock. SE single-CPU
      // runs share the root clock; use the local tick-to-cycle via the
      // SimObject's own clock domain is not available here — use curTick and
      // the standard 1000 ticks/cycle SE convention (same as CHAOSArmTLB's
      // advisory window; honest limitation, no per-domain resolution).
      if (max_faults && faults_injected_count >= max_faults)
          return false;
      if (last_clock && curTick() > last_clock * 1000)
          return false;
      if (curTick() < first_clock * 1000) {
          stats->numOutOfWindow++;
          return false;
      }
      stats->numInWindowChecks++;
      if (probability >= 1.0f)
          return true;
      std::uniform_real_distribution<float> dist(0.0f, 1.0f);
      return dist(rng) < probability;
  }

  void
  CHAOSExMon::writeLog(const std::string &type, Addr paddr, ContextID cid)
  {
      if (!write_log || !log_stream)
          return;
      *(log_stream->stream())
          << "Tick: " << curTick()
          << ", Site: exclusive_monitor"
          << ", Mode: " << type
          << ", Paddr: 0x" << std::hex << paddr << std::dec
          << ", Context: " << cid
          << ", Count: " << faults_injected_count
          << "\n";
  }

  void
  CHAOSExMon::maybeDropReservation(memory::AbstractMemory *mem,
                                   const RequestPtr &req, Addr paddr)
  {
      if (mode != Mode::ClearReservation)
          return;
      if (!shouldInject())
          return;
      // Drop the reservation this LDXR just registered: erase the
      // (context, addr) record from the host's lockedAddrList.
      mem->chaosEraseReservation(req, paddr);
      faults_injected_count++;
      stats->numFaultsInjected++;
      stats->numClearReservations++;
      writeLog("clear_reservation", paddr,
               req->hasContextId() ? req->contextId() : InvalidContextID);
  }

  bool
  CHAOSExMon::maybeKeepReservation(memory::AbstractMemory *mem,
                                   ContextID owner_cid,
                                   ContextID requestor_cid, Addr paddr)
  {
      if (mode != Mode::StaleReservation)
          return false;
      if (!shouldInject())
          return false;
      // Suppress the erase: owner_cid's reservation on paddr survives this
      // conflicting write — its later STXR will falsely succeed.
      faults_injected_count++;
      stats->numFaultsInjected++;
      stats->numStaleReservations++;
      writeLog("stale_reservation", paddr, owner_cid);
      return true;
  }

} // namespace gem5

