#ifndef __MEM_CHAOSExMon_HH__
#define __MEM_CHAOSExMon_HH__

#include <random>
#include <string>
#include <cstdint>

#include "sim/sim_object.hh"
#include "base/types.hh"
#include "params/CHAOSExMon.hh"
#include "base/output.hh"

namespace gem5
{

  class CacheBlk;
  class Packet;

  // S3-7 (plan §5.4B): exclusive-monitor fault injector. With caches, the
  // gem5 SE model of ARM's local exclusive monitor is CacheBlk::lockList
  // (cache_blk.hh trackLoadLocked/checkWrite/clearLoadLocks); the
  // AbstractMemory::lockedAddrList path is no-cache-only. CacheBlk has no
  // SimObject context, so this injector is reached via the namespace-level
  // chaos_exmon_g pointer (set in ctor, cleared in dtor; single injector
  // per simulation — same discipline as the other CHAOS hooks).
  //   clear_reservation  — drop a just-registered LDXR reservation
  //                       (chronic STXR failure)
  //   stale_reservation  — keep a foreign context's reservation alive
  //                       across a conflicting write (STXR false-success,
  //                       lost-update SDC)
  class CHAOSExMon : public SimObject
  {
    public:
      CHAOSExMon(const CHAOSExMonParams &p);
      ~CHAOSExMon();

      enum class Mode {
          ClearReservation,
          StaleReservation
      };

      // Hook 1 (CacheBlk::trackLoadLocked, AFTER the reservation is
      // registered): clear_reservation may drop it.
      void blkDropReservation(CacheBlk *blk, PacketPtr pkt);

      // Hook 2 (CacheBlk::checkWrite, normal-write branch, BEFORE
      // clearLoadLocks): stale_reservation keeps foreign reservations
      // alive. Returns true when the erase must be skipped.
      bool blkKeepReservation(CacheBlk *blk, const RequestPtr &req);

    private:
      Mode mode;
      float probability;
      uint64_t first_clock, last_clock;
      uint64_t max_faults;
      uint64_t faults_injected_count;
      bool write_log;
      std::mt19937 rng;
      OutputStream *log_stream = nullptr;

      bool shouldInject();
      void writeLog(const char *type, Addr paddr, ContextID cid);

      struct CHAOSExMonStats : public statistics::Group
      {
          statistics::Scalar numFaultsInjected;
          statistics::Scalar numClearReservations;   // LDXR reservations dropped
          statistics::Scalar numStaleReservations;   // erases suppressed
          statistics::Scalar numInWindowChecks;      // hook invocations in window
          statistics::Scalar numOutOfWindow;         // hook invocations pre-window

          CHAOSExMonStats(statistics::Group *parent);
      };

      std::unique_ptr<CHAOSExMonStats> stats;
  };

  // namespace-level hook pointer (cache_blk.hh checks this)
  extern CHAOSExMon *chaos_exmon_g;

} // namespace gem5

#endif // __MEM_CHAOSExMon_HH__

#include "mem/CHAOSExMon/CHAOSExMon.hh"

#include "base/output.hh"
#include "base/types.hh"
#include "mem/cache/cache_blk.hh"
#include "mem/packet.hh"
#include "mem/request.hh"
#include "params/CHAOSExMon.hh"
#include "sim/sim_object.hh"

namespace gem5
{

  // namespace-level hook pointer (checked by CacheBlk's inline LLSC methods)
  CHAOSExMon *chaos_exmon_g = nullptr;

  CHAOSExMon::CHAOSExMonStats::CHAOSExMonStats(statistics::Group *parent)
      : statistics::Group(parent, "CHAOSExMon"),
        ADD_STAT(numFaultsInjected, statistics::units::Count::get(),
                 "Total reservations corrupted (G5-capped)"),
        ADD_STAT(numClearReservations, statistics::units::Count::get(),
                 "LDXR reservations dropped (clear_reservation mode)"),
        ADD_STAT(numStaleReservations, statistics::units::Count::get(),
                 "reservation erases suppressed (stale_reservation mode)"),
        ADD_STAT(numInWindowChecks, statistics::units::Count::get(),
                 "hook invocations inside the injection window"),
        ADD_STAT(numOutOfWindow, statistics::units::Count::get(),
                 "hook invocations before first_clock (skipped)")
  {
  }

  CHAOSExMon::CHAOSExMon(const CHAOSExMonParams &p)
      : SimObject(p),
        probability(p.probability),
        first_clock(p.firstClock), last_clock(p.lastClock),
        max_faults(p.maxFaults),
        faults_injected_count(0),
        write_log(p.writeLog),
        rng(p.rngSeed),
        stats(std::make_unique<CHAOSExMonStats>(this))
  {
      const std::string &m = p.mode;
      if (m == "clear_reservation")      mode = Mode::ClearReservation;
      else if (m == "stale_reservation") mode = Mode::StaleReservation;
      else
          panic("CHAOSExMon: unknown mode '%s' "
                "(clear_reservation|stale_reservation)", m);

      // Attach the namespace-level hook pointer (CacheBlk inline methods
      // check chaos_exmon_g). Single injector per simulation.
      chaos_exmon_g = this;

      if (write_log) {
          log_stream = simout.findOrCreate("exmon_injections.log");
          *(log_stream->stream())
              << "CHAOSExMon attached (CacheBlk::lockList hook), mode=" << m
              << " probability=" << probability
              << " first_clock=" << first_clock
              << " last_clock=" << last_clock
              << " max_faults=" << max_faults
              << " rng_seed=" << p.rngSeed << "\n";
      }
  }

  CHAOSExMon::~CHAOSExMon()
  {
      if (chaos_exmon_g == this)
          chaos_exmon_g = nullptr;
  }

  bool
  CHAOSExMon::shouldInject()
  {
      // Time window on curTick (1000 ticks/cycle SE convention — same
      // advisory as CHAOSArmTLB; honest limitation, no per-domain cycle
      // resolution).
      if (max_faults && faults_injected_count >= max_faults)
          return false;
      if (last_clock && curTick() > last_clock * 1000)
          return false;
      if (curTick() < first_clock * 1000) {
          stats->numOutOfWindow++;
          return false;
      }
      stats->numInWindowChecks++;
      if (probability >= 1.0f)
          return true;
      std::uniform_real_distribution<float> dist(0.0f, 1.0f);
      return dist(rng) < probability;
  }

  void
  CHAOSExMon::writeLog(const char *type, Addr paddr, ContextID cid)
  {
      if (!write_log || !log_stream)
          return;
      *(log_stream->stream())
          << "Tick: " << curTick()
          << ", Site: exclusive_monitor"
          << ", Mode: " << type
          << ", Paddr: 0x" << std::hex << paddr << std::dec
          << ", Context: " << cid
          << ", Count: " << faults_injected_count
          << "\n";
  }

  void
  CHAOSExMon::blkDropReservation(CacheBlk *blk, PacketPtr pkt)
  {
      if (mode != Mode::ClearReservation)
          return;
      if (!shouldInject())
          return;
      // Drop every reservation this LDXR just registered on the block
      // (same-context intersecting entries — trackLoadLocked put one).
      blk->lockList.remove_if(
          [&pkt](const CacheBlk::Lock &l) {
              return l.intersects(pkt->req);
          });
      faults_injected_count++;
      stats->numFaultsInjected++;
      stats->numClearReservations++;
      writeLog("clear_reservation", pkt->req->getPaddr(),
               pkt->req->hasContextId() ? pkt->req->contextId()
                                        : InvalidContextID);
  }

  bool
  CHAOSExMon::blkKeepReservation(CacheBlk *blk, const RequestPtr &req)
  {
      if (mode != Mode::StaleReservation)
          return false;
      // Only fires when there IS a foreign reservation to keep alive
      // (otherwise clearLoadLocks is a no-op anyway).
      bool has_foreign = false;
      for (const auto &l : blk->lockList) {
          if (l.intersects(req) &&
              (!req->hasContextId() || l.contextId != req->contextId())) {
              has_foreign = true;
              break;
          }
      }
      if (!has_foreign)
          return false;
      if (!shouldInject())
          return false;
      // Suppress the clearLoadLocks: the foreign reservation survives this
      // conflicting write — its later STXR will falsely succeed.
      faults_injected_count++;
      stats->numFaultsInjected++;
      stats->numStaleReservations++;
      Addr pa = req->getPaddr();
      writeLog("stale_reservation", pa,
               req->hasContextId() ? req->contextId() : InvalidContextID);
      return true;
  }

} // namespace gem5

